#[path = "solution.rs"]
mod solution;

use solution::first_content_line;

#[test]
fn skips_blank_lines_and_preserves_selected_line_whitespace() {
    let text = "\n   \n\t\r\n  selected text  \t\r\nnext";
    assert_eq!(first_content_line(text), Some("  selected text  \t"));
}

#[test]
fn supports_lf_crlf_and_unterminated_final_lines() {
    assert_eq!(first_content_line("\r\nhello\r\nworld"), Some("hello"));
    assert_eq!(first_content_line("\n\nfinal line"), Some("final line"));
    assert_eq!(first_content_line("content\n"), Some("content"));
}

#[test]
fn uses_unicode_whitespace_classification() {
    let text = "\u{2003}\n\u{00a0}\t\r\n\u{2003}λ\u{2003}\n";
    assert_eq!(first_content_line(text), Some("\u{2003}λ\u{2003}"));
}

#[test]
fn isolated_carriage_return_is_line_content_and_whitespace() {
    assert_eq!(first_content_line("\r\n\r\n\r x \r\n"), Some("\r x \r"));
    assert_eq!(first_content_line("\r"), None);
}

#[test]
fn empty_and_whitespace_only_inputs_have_no_content_line() {
    assert_eq!(first_content_line(""), None);
    assert_eq!(first_content_line(" \t\n\r\n\u{2002}"), None);
}

#[test]
fn returned_value_is_a_slice_of_the_original_input() {
    let text = String::from("\n  borrowed  \n");
    let line = first_content_line(&text).unwrap();
    assert_eq!(line, "  borrowed  ");
    assert!(line.as_ptr() >= text.as_ptr());
    assert!(line.as_ptr() < unsafe { text.as_ptr().add(text.len()) });
}

